<script setup>
import { computed, ref, watch } from 'vue';
import { Link, router, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';

const props=defineProps({article:Object,selectedWords:Array,coverUrl:String,detailImageUrl:String});
const editing=computed(()=>!!props.article);
const initialParagraphs=(props.article?.body||[{sentences:[''],translation:''}]).map(p=>({sentences:(p.sentences||[]).join('\n'),translation:p.translation||''}));
const articleForm=useForm({title:props.article?.title||'',translation:props.article?.translation||'',level:props.article?.level||'',minutes:props.article?.minutes||'',slug:props.article?.slug||'',rightsType:props.article?.rights_type||'',rightsNote:props.article?.rights_note||'',paragraphs:initialParagraphs,coverImage:null,detailImage:null});
const analysis=props.article?.analysis||{};
const analysisForm=useForm({type:analysis.type||'richtext',format:analysis.format||'html',html:analysis.html||'',url:analysis.url||'',title:analysis.title||'',summary:analysis.summary||''});
const selected=ref((props.selectedWords||[]).map(w=>({...w,id:Number(w.id)})));
const search=ref('');const results=ref([]);const searching=ref(false);let timer;
const wordForm=useForm({wordIds:selected.value.map(w=>w.id)});
const questionForm=useForm({questions:(props.article?.questions||[]).map(q=>({id:q.id,questionType:q.question_type||'细节理解',kind:q.kind||'choice',prompt:q.prompt||'',promptCn:q.prompt_cn||'',options:(q.options||[]).join('\n'),answer:q.kind==='choice'?String.fromCharCode(65+(Number(q.answer)||0)):(q.answer||''),explanation:q.explanation||''}))});
const analysisEditor=ref(null);const quickDialog=ref(null);const coverPreview=ref(props.coverUrl||'');const detailPreview=ref(props.detailImageUrl||'');
const quick=ref({open:false,busy:false,error:'',headword:'',meaning:'',ipa:'',partOfSpeech:''});
const letters='ABCDEFGH';
watch(search,value=>{clearTimeout(timer);if(!value.trim()){results.value=[];return}timer=setTimeout(async()=>{searching.value=true;try{const res=await fetch(`/admin/articles/${props.article.id}/word-options?q=${encodeURIComponent(value)}`,{credentials:'same-origin',headers:{Accept:'application/json'}});const data=await res.json();results.value=res.ok?(data.items||[]):[]}finally{searching.value=false}},250)});
watch(()=>quick.value.open,open=>{if(!quickDialog.value)return;open?quickDialog.value.showModal():quickDialog.value.close()});
function saveArticle(){articleForm.transform(data=>({...data,paragraphs:data.paragraphs.map(p=>({...p,sentences:Array.isArray(p.sentences)?p.sentences.join('\n'):p.sentences}))})).submit(editing.value?'put':'post',editing.value?`/admin/articles/${props.article.id}`:'/admin/articles',{forceFormData:true});}
function saveAnalysis(){analysisForm.put(`/admin/articles/${props.article.id}/analysis`)}
function syncWords(){wordForm.wordIds=selected.value.map(w=>w.id);wordForm.put(`/admin/articles/${props.article.id}/words`)}
function saveQuestions(){questionForm.put(`/admin/articles/${props.article.id}/questions`)}
function addParagraph(){articleForm.paragraphs.push({sentences:'',translation:''})}
function addQuestion(){questionForm.questions.push({id:null,questionType:'细节理解',kind:'choice',prompt:'',promptCn:'',options:'',answer:'A',explanation:''})}
function questionOptions(q){return q.options.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}
function addWord(w){if(!selected.value.some(x=>Number(x.id)===Number(w.id)))selected.value.push({...w,id:Number(w.id)});}
function removeWord(id){selected.value=selected.value.filter(w=>Number(w.id)!==Number(id))}
async function quickCreate(){const headword=quick.value.headword.trim();if(!headword)return;quick.value.error='';quick.value.busy=true;try{const response=await fetch(`/admin/articles/${props.article.id}/words/new`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({headword,meaning:quick.value.meaning,ipa:quick.value.ipa,partOfSpeech:quick.value.partOfSpeech})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat().join(' ')||'创建失败');addWord(data);quick.value.open=false;quick.value.headword='';quick.value.meaning='';quick.value.ipa='';quick.value.partOfSpeech=''}catch(e){quick.value.error=e.message}finally{quick.value.busy=false}}
function imageChanged(event,key){const file=event.target.files?.[0];if(!file)return;const url=URL.createObjectURL(file);if(key==='cover'){coverPreview.value=url;articleForm.coverImage=file}else{detailPreview.value=url;articleForm.detailImage=file}}
function analysisCommand(command,value=null){analysisEditor.value?.focus();document.execCommand(command,false,value);analysisForm.html=analysisEditor.value?.innerHTML||''}
function onAnalysisInput(){analysisForm.html=analysisEditor.value?.innerHTML||''}
function toggleFormat(format){if(analysisForm.format==='html'&&analysisEditor.value)analysisForm.html=analysisEditor.value.innerHTML;analysisForm.format=format}
function lettersFor(q){return letters.slice(0,Math.max(2,Math.min(8,questionOptions(q).length))).split('')}
</script>

<template><AdminLayout :title="editing?'编辑文章':'新建文章'" section="内容管理 / 精读文章" :description="editing?`文章 ID #${article.id} · 更新正文、解析、词汇与阅读题`:'新建文章，保存后可继续添加解析、词汇与阅读题。'"><template #actions><Link class="btn secondary" href="/admin/articles">← 返回列表</Link></template>
  <div class="split-panel"><div class="form-stack">
    <section class="card"><div class="card-header"><div><h2>基本信息与正文</h2><p>文章标题、内容和版权来源</p></div></div><div class="card-body"><form class="form-stack" @submit.prevent="saveArticle">
      <div class="form-grid"><div class="form-field"><label>英文标题 <b class="required-mark">*</b></label><input v-model="articleForm.title" class="input" required></div><div class="form-field"><label>中文标题</label><input v-model="articleForm.translation" class="input"></div><div class="form-field"><label>阅读级别</label><input v-model="articleForm.level" class="input" placeholder="如：初级"></div><div class="form-field"><label>预计阅读分钟数</label><input v-model="articleForm.minutes" class="input" type="number" min="1"></div><div class="form-field"><label>内容标识 slug</label><input v-model="articleForm.slug" class="input"></div></div>
      <div class="article-images"><div class="form-field"><label>方形封面图</label><div class="cover-upload"><div class="cover-preview square"><img v-if="coverPreview" :src="coverPreview" alt="封面预览"><span v-else>暂无封面</span></div><div class="cover-upload-controls"><input type="file" accept="image/jpeg,image/png,image/webp" @change="imageChanged($event,'cover')"><p class="form-hint">建议 1:1 方图，最大 4 MB。</p></div></div></div><div class="form-field"><label>详情横图</label><div class="cover-upload"><div class="cover-preview landscape"><img v-if="detailPreview" :src="detailPreview" alt="详情图预览"><span v-else>暂无详情图</span></div><div class="cover-upload-controls"><input type="file" accept="image/jpeg,image/png,image/webp" @change="imageChanged($event,'detail')"><p class="form-hint">建议 16:9 横图，最大 4 MB。</p></div></div></div></div>
      <div><div class="card-header nested-header"><div><h2>文章正文</h2><p>每行一句英文；中文翻译按段填写。</p></div></div><div v-for="(p,i) in articleForm.paragraphs" :key="i" class="paragraph"><div class="paragraph-head"><span>第 {{i+1}} 段</span><button v-if="articleForm.paragraphs.length>1" class="ghost" type="button" @click="articleForm.paragraphs.splice(i,1)">移除</button></div><div class="form-grid"><div class="form-field wide"><label>英文句子（一行一句） <b class="required-mark">*</b></label><textarea v-model="p.sentences" class="textarea" required></textarea></div><div class="form-field wide"><label>中文翻译 <b class="required-mark">*</b></label><textarea v-model="p.translation" class="textarea" required></textarea></div></div></div><button class="btn secondary" type="button" @click="addParagraph">＋ 添加段落</button></div>
      <div class="form-grid"><div class="form-field"><label>版权来源类型 <b class="required-mark">*</b></label><select v-model="articleForm.rightsType" class="select"><option value="">请选择</option><option value="original">原创</option><option value="authorized">已获授权</option><option value="public_domain">公版作品</option><option value="excerpt">摘编 / 节选</option><option value="other">其他</option></select></div><div class="form-field wide"><label>版权与来源说明 <b class="required-mark">*</b></label><textarea v-model="articleForm.rightsNote" class="textarea"></textarea></div></div>
      <div class="section-actions"><button class="btn" :disabled="articleForm.processing">{{articleForm.processing?'正在保存…':'保存文章'}}</button><span class="helper">文章默认为草稿；发布操作在文章列表进行。</span></div>
    </form></div></section>
    <template v-if="editing">
      <section class="card"><div class="card-header"><div><h2>本文语法解析</h2><p>可粘贴 Markdown，前台会显示为排版后的内容。</p></div></div><div class="card-body"><form class="form-stack" @submit.prevent="saveAnalysis"><div class="form-grid"><div class="form-field"><label>内容形式</label><select v-model="analysisForm.type" class="select"><option value="richtext">富文本内容</option><option value="officialAccount">公众号文章链接</option></select></div><div v-if="analysisForm.type==='richtext'" class="form-field"><label>编辑格式</label><div class="format-switch"><button type="button" class="format-option" :class="{active:analysisForm.format==='html'}" @click="toggleFormat('html')">富文本</button><button type="button" class="format-option" :class="{active:analysisForm.format==='markdown'}" @click="toggleFormat('markdown')">Markdown</button></div></div></div><template v-if="analysisForm.type==='richtext'"><div v-if="analysisForm.format==='html'" class="form-field"><div class="toolbar"><button type="button" @click="analysisCommand('bold')">粗体</button><button type="button" @click="analysisCommand('italic')">斜体</button><button type="button" @click="analysisCommand('insertUnorderedList')">列表</button><button type="button" @click="analysisCommand('formatBlock','h3')">小标题</button></div><div ref="analysisEditor" class="rich-editor" contenteditable="true" v-html="analysisForm.html" @input="onAnalysisInput"></div></div><textarea v-else v-model="analysisForm.html" class="textarea markdown-editor" placeholder="粘贴 Markdown 内容…"></textarea></template><div v-else class="form-grid"><div class="form-field wide"><label>公众号文章链接</label><input v-model="analysisForm.url" class="input" type="url"></div><div class="form-field"><label>文章标题</label><input v-model="analysisForm.title" class="input"></div><div class="form-field"><label>摘要</label><input v-model="analysisForm.summary" class="input"></div></div><div class="section-actions"><button class="btn" :disabled="analysisForm.processing">保存解析</button></div></form></div></section>
      <section class="card"><div class="card-header"><div><h2>重点词汇</h2><p>搜索添加到本文；单词可在单词管理中完善详解。</p></div><span class="helper">已选 {{selected.length}} 个</span></div><div class="card-body"><div class="selected-words"><span v-for="w in selected" :key="w.id" class="selected-word"><span>{{w.headword}} <small>{{w.meaning}}</small><em v-if="w.status!=='published'">草稿</em></span><button type="button" @click="removeWord(w.id)">×</button></span></div><div class="picker-tools"><input v-model="search" class="input picker-search" placeholder="输入英文单词或中文释义搜索"><button class="btn secondary" @click="quick.open=true">＋ 新建单词</button></div><div class="word-picker"><p v-if="searching" class="helper">正在搜索…</p><p v-else-if="search.trim().length===0" class="helper">输入至少一个字，查看匹配结果。</p><p v-else-if="!results.length" class="helper">没有匹配的单词。</p><div v-for="w in results" :key="w.id" class="word-option"><span>{{w.headword}} <small>{{w.meaning}}</small><em v-if="w.status!=='published'">草稿</em></span><button class="btn small secondary" :disabled="selected.some(x=>x.id===Number(w.id))" @click="addWord(w)">{{selected.some(x=>x.id===Number(w.id))?'已添加':'添加'}}</button></div></div><button class="btn" :disabled="wordForm.processing" @click="syncWords">保存重点词汇</button></div></section>
      <section class="card"><div class="card-header"><div><h2>阅读理解题</h2><p>按题目顺序展示；支持选择题和填空题。</p></div><button class="btn secondary" @click="addQuestion">＋ 添加题目</button></div><div class="card-body"><form @submit.prevent="saveQuestions"><div v-for="(q,i) in questionForm.questions" :key="q.id||`new-${i}`" class="reading-question"><div class="question-editor-head"><strong>题目 {{i+1}}</strong><button class="ghost" type="button" @click="questionForm.questions.splice(i,1)">移除</button></div><div class="form-grid"><div class="form-field"><label>题型</label><select v-model="q.questionType" class="select"><option v-for="t in ['细节理解','主旨大意','推理判断','词义猜测','标题归纳','其他']" :key="t">{{t}}</option></select></div><div class="form-field"><label>作答方式</label><select v-model="q.kind" class="select"><option value="choice">选择题</option><option value="fill">填空题</option></select></div><div class="form-field wide"><label>英文题目 *</label><textarea v-model="q.prompt" class="textarea" required></textarea></div><div class="form-field wide"><label>中文题目</label><textarea v-model="q.promptCn" class="textarea"></textarea></div><div v-if="q.kind==='choice'" class="form-field wide"><label>选项（每行一个）</label><textarea v-model="q.options" class="textarea"></textarea><p class="form-hint">填写 2–8 个选项。</p></div><div class="form-field"><label>{{q.kind==='choice'?'正确选项':'参考答案'}}</label><select v-if="q.kind==='choice'" v-model="q.answer" class="select"><option v-for="letter in lettersFor(q)" :key="letter">{{letter}}</option></select><input v-else v-model="q.answer" class="input"></div><div class="form-field wide"><label>答案解析</label><textarea v-model="q.explanation" class="textarea"></textarea></div></div></div><div class="section-actions"><button class="btn" :disabled="questionForm.processing">保存阅读理解题</button></div></form></div></section>
    </template>
  </div><aside class="form-stack"><section class="card"><div class="card-header"><h2>编辑提示</h2></div><div class="card-body"><p class="helper">文章保存后默认为草稿。发布和下架操作在文章列表中进行。</p></div></section><section v-if="editing" class="card"><div class="card-header"><h2>文章信息</h2></div><div class="card-body"><div class="helper">ID：#{{article.id}}</div><div class="helper" style="margin-top:8px">最后更新：{{article.updated_at}}</div></div></section></aside></div>
  <dialog ref="quickDialog" class="word-dialog" @close="quick.open=false"><form class="form-stack" @submit.prevent="quickCreate"><div class="dialog-head"><div><h3>添加单词</h3><p>新词先保存为草稿，可稍后补充详解。</p></div><button type="button" class="dialog-close" @click="quick.open=false">×</button></div><div class="form-grid"><div class="form-field"><label>单词 *</label><input v-model="quick.headword" class="input" required></div><div class="form-field"><label>释义 *</label><input v-model="quick.meaning" class="input" required></div><div class="form-field"><label>音标</label><input v-model="quick.ipa" class="input"></div><div class="form-field"><label>词性</label><input v-model="quick.partOfSpeech" class="input"></div></div><p v-if="quick.error" class="dialog-error">{{quick.error}}</p><button class="btn" :disabled="quick.busy">创建并添加到本文</button></form></dialog>
</AdminLayout></template>
